const msg = $json.messages?.[0];

if (!msg?.id) {
  throw new Error('Missing WhatsApp message ID.');
}

if (!msg?.from) {
  throw new Error('Missing WhatsApp sender number.');
}

const phoneNumberId = String($json.metadata?.phone_number_id || '').trim();
if (!phoneNumberId) {
  throw new Error('Missing WhatsApp phone number ID.');
}

const digitsOnly = String(msg.from).replace(/[^0-9]/g, '');
const normalizedPhone = '+' + digitsOnly;
const phonePattern = /^\+[1-9][0-9]{6,14}$/;

if (!phonePattern.test(normalizedPhone)) {
  throw new Error('Invalid WhatsApp sender number.');
}

const messageText = String(msg.text?.body || '').trim();
if (!messageText) {
  throw new Error('Inbound text message has an empty body.');
}

return [{
  json: {
    normalized_phone: normalizedPhone,
    wa_message_id: String(msg.id),
    message_text: messageText,
    wa_timestamp: msg.timestamp || null,
    phone_number_id: phoneNumberId,
    received_at: new Date().toISOString()
  }
}];

